<?php
declare(strict_types=1);
final class InterviewService {
 private PDO $db;private OpenAIClient $openai;
 public function __construct(PDO $db,OpenAIClient $openai){$this->db=$db;$this->openai=$openai;}
 private function context(int $companyId,int $grantId):array {$c=$this->db->prepare('SELECT * FROM companies WHERE id=?');$c->execute([$companyId]);$company=$c->fetch();$g=$this->db->prepare('SELECT * FROM grant_programs WHERE id=?');$g->execute([$grantId]);$grant=$g->fetch();if(!$company||!$grant)throw new InvalidArgumentException('기업 또는 공고를 찾을 수 없습니다.');$d=$this->db->prepare("SELECT company_id,grant_program_id,analysis_json FROM documents WHERE analysis_status='completed' AND (company_id=? OR grant_program_id=?) ORDER BY analyzed_at DESC");$d->execute([$companyId,$grantId]);return ['company'=>$company,'grant'=>$grant,'analyses'=>$d->fetchAll()];}
 public function generate(int $companyId,int $grantId,int $userId):array {$schema=['type'=>'object','additionalProperties'=>false,'required'=>['questions'],'properties'=>['questions'=>['type'=>'array','minItems'=>8,'maxItems'=>20,'items'=>['type'=>'object','additionalProperties'=>false,'required'=>['key','category','evaluation_item','question','why','required_evidence','max_score'],'properties'=>['key'=>['type'=>'string'],'category'=>['type'=>'string'],'evaluation_item'=>['type'=>'string'],'question'=>['type'=>'string'],'why'=>['type'=>'string'],'required_evidence'=>['type'=>'string'],'max_score'=>['type'=>'number']]]]]];$questions=$this->openai->structured('기업 분석과 공모사업의 신청요건·평가항목을 비교하여 미팅용 서술형 질문지를 만드세요. 각 질문은 기업이 현재상태, 수치, 원인, 근거, 목표상태를 충분히 서술하도록 작성하세요. 필수자격 확인, 정량 KPI, 실행역량, 데이터 준비도, 예산·자부담, 사후운영 질문을 포함하고 각 질문이 어떤 평가항목을 검증하는지 명시하세요. 문서에 없는 사실은 추측하지 마세요.',$this->context($companyId,$grantId),$schema,'interview_questions');$st=$this->db->prepare("INSERT INTO interview_sessions(company_id,grant_program_id,status,questions_json,created_by)VALUES(?,?,'draft',?,?)");$st->execute([$companyId,$grantId,json_encode($questions['questions'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$userId]);return ['session_id'=>(int)$this->db->lastInsertId(),'questions'=>$questions['questions']];}
 public function saveAnswers(int $sessionId,array $answers):void {$this->db->beginTransaction();try{$st=$this->db->prepare('INSERT INTO interview_answers(interview_session_id,question_key,answer)VALUES(?,?,?) ON DUPLICATE KEY UPDATE answer=VALUES(answer),updated_at=CURRENT_TIMESTAMP');foreach($answers as$a){if(empty($a['key'])||trim((string)($a['answer']??''))==='')continue;$st->execute([$sessionId,(string)$a['key'],trim((string)$a['answer'])]);}$this->db->prepare("UPDATE interview_sessions SET status='in_progress' WHERE id=?")->execute([$sessionId]);$this->db->commit();}catch(Throwable $e){$this->db->rollBack();throw$e;}}
 public function finalize(int $sessionId,int $userId):array {$s=$this->db->prepare('SELECT * FROM interview_sessions WHERE id=?');$s->execute([$sessionId]);$session=$s->fetch();if(!$session)throw new InvalidArgumentException('미팅 질문지를 찾을 수 없습니다.');$a=$this->db->prepare('SELECT question_key,answer FROM interview_answers WHERE interview_session_id=?');$a->execute([$sessionId]);$answers=$a->fetchAll();$schema=['type'=>'object','additionalProperties'=>false,'required'=>['eligibility_passed','interview_score','answer_evaluations','reasons','risks','required_actions'],'properties'=>['eligibility_passed'=>['type'=>'boolean'],'interview_score'=>['type'=>'number','minimum'=>0,'maximum'=>100],'answer_evaluations'=>['type'=>'array','items'=>['type'=>'object','additionalProperties'=>false,'required'=>['key','score','evidence','risk_level'],'properties'=>['key'=>['type'=>'string'],'score'=>['type'=>'number','minimum'=>0,'maximum'=>100],'evidence'=>['type'=>'string'],'risk_level'=>['type'=>'string','enum'=>['low','medium','high']]]]],'reasons'=>['type'=>'array','items'=>['type'=>'string']],'risks'=>['type'=>'array','items'=>['type'=>'string']],'required_actions'=>['type'=>'array','items'=>['type'=>'string']]]];$context=$this->context((int)$session['company_id'],(int)$session['grant_program_id']);$context['questions']=json_decode($session['questions_json'],true);$context['answers']=$answers;$result=$this->openai->structured('공고 필수요건과 평가항목을 기준으로 미팅 답변을 평가하세요. 답변에 없는 내용을 추측하지 말고 구체적 근거가 없는 답변은 낮게 평가하세요.',$context,$schema,'interview_assessment');$diag=(float)($this->db->query('SELECT COALESCE(MAX(total_score),0) FROM diagnostics WHERE company_id='.(int)$session['company_id'])->fetchColumn());$match=(float)($this->db->query('SELECT COALESCE(MAX(total_score),0) FROM grant_matches WHERE company_id='.(int)$session['company_id'].' AND grant_program_id='.(int)$session['grant_program_id'])->fetchColumn());$interview=(float)$result['interview_score'];$final=round($diag*.30+$match*.30+$interview*.40,2);$decision=!$result['eligibility_passed']?'reject':($final>=80?'recommend':($final>=65?'conditional':($final>=50?'hold':'reject')));$this->db->beginTransaction();try{$up=$this->db->prepare('UPDATE interview_answers SET score=?,evidence=?,risk_level=? WHERE interview_session_id=? AND question_key=?');foreach($result['answer_evaluations']as$ev)$up->execute([$ev['score'],$ev['evidence'],$ev['risk_level'],$sessionId,$ev['key']]);$ins=$this->db->prepare('INSERT INTO company_decisions(company_id,grant_program_id,interview_session_id,eligibility_passed,diagnostic_score,match_score,interview_score,final_score,decision,reasons_json,risks_json,required_actions_json,decided_at,decided_by)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),?)');$ins->execute([$session['company_id'],$session['grant_program_id'],$sessionId,$result['eligibility_passed']?1:0,$diag,$match,$interview,$final,$decision,json_encode($result['reasons'],JSON_UNESCAPED_UNICODE),json_encode($result['risks'],JSON_UNESCAPED_UNICODE),json_encode($result['required_actions'],JSON_UNESCAPED_UNICODE),$userId]);$this->db->prepare("UPDATE interview_sessions SET status='evaluated',completed_at=NOW() WHERE id=?")->execute([$sessionId]);$this->db->commit();}catch(Throwable$e){$this->db->rollBack();throw$e;}return ['decision_id'=>(int)$this->db->lastInsertId(),'eligibility_passed'=>$result['eligibility_passed'],'scores'=>['diagnostic'=>$diag,'match'=>$match,'interview'=>$interview,'final'=>$final],'decision'=>$decision,'reasons'=>$result['reasons'],'risks'=>$result['risks'],'required_actions'=>$result['required_actions']];}
}
